param([string]$ResultRoot='',[string]$OutputPath='')
$ErrorActionPreference='Stop';$repo=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$root=if($ResultRoot){(Resolve-Path $ResultRoot).Path}else{Join-Path $repo 'experiment\results\experiment-1-58'};$out=if($OutputPath){$OutputPath}else{Join-Path $root 'aggregate.json'}
function Pct($v,$p){$a=@($v|Where-Object {$null -ne $_}|Sort-Object);if(!$a.Count){return $null};$i=[math]::Ceiling($p*$a.Count)-1;if($i-lt0){$i=0};$a[$i]}
function Resource($path){$c=@();$m=@();$p=@();foreach($l in Get-Content $path){try{$o=$l|ConvertFrom-Json;$z=$o.value-split',';if($z[0]-match'flux-corrected'){$c+=[double]($z[1]-replace'%','');$m+=[double](($z[2]-split'/')[0]-replace'[^0-9.]','');$p+=[int]$z[3]}}catch{}};[ordered]@{cpuAvg=if($c){($c|Measure-Object -Average).Average}else{$null};cpuP50=Pct $c .5;cpuP95=Pct $c .95;cpuPeak=if($c){($c|Measure-Object -Maximum).Maximum}else{$null};memoryAvg=if($m){($m|Measure-Object -Average).Average}else{$null};memoryP95=Pct $m .95;memoryPeak=if($m){($m|Measure-Object -Maximum).Maximum}else{$null};pidsAvg=if($p){($p|Measure-Object -Average).Average}else{$null};pidsPeak=if($p){($p|Measure-Object -Maximum).Maximum}else{$null}}}
function Provider($path){$by=@{};foreach($l in Get-Content $path){try{$o=$l|ConvertFrom-Json;foreach($m in @($o.payload.metrics)){if($m.name-match'active.connections|pending.connections' -and $m.tags.name-match'doeng-(token|ai|storage)'){$k="$($m.tags.name)/$(if($m.name-match'pending'){'pending'}else{'active'})";if(!$by.ContainsKey($k)){$by[$k]=@()};$by[$k]+=[double]$m.value}}}catch{}};$r=[ordered]@{};foreach($s in 'doeng-token','doeng-ai','doeng-storage'){$a=@($by["$s/active"]);$p=@($by["$s/pending"]);$r[$s]=[ordered]@{activeAvg=if($a){($a|Measure-Object -Average).Average}else{$null};activeP95=Pct $a .95;activePeak=if($a){($a|Measure-Object -Maximum).Maximum}else{$null};pendingAvg=if($p){($p|Measure-Object -Average).Average}else{$null};pendingP95=Pct $p .95;pendingPeak=if($p){($p|Measure-Object -Maximum).Maximum}else{$null};pendingNonZero=@($p|Where-Object {$_-gt0}).Count}};$r}
function Buckets($d,$s){$req=@((Get-Content (Join-Path $d 'load\client-results.json') -Raw|ConvertFrom-Json).requests);$start=[datetime]$s.startedAt;$out=@();foreach($i in 0..5){$lo=$start.AddSeconds(5*$i);$hi=$start.AddSeconds(5*($i+1));$q=@($req|Where-Object {$t=[datetime]$_.completedAt;$t-ge$lo -and $t-lt$hi});$out+=[ordered]@{bucket="T$i";acceptedHttp200=$(@($q|Where-Object {$_.status -eq 200}).Count);acceptedPerSecond=$(@($q|Where-Object {$_.status -eq 200}).Count/5);http500=$(@($q|Where-Object {$_.status -eq 500}).Count);timeout=$(@($q|Where-Object {$_.status -eq 'AbortError'}).Count);connectionError=$(@($q|Where-Object {$_.transport -eq 'CONNECTION_ERROR'}).Count);inFlightAtSample='NOT_AVAILABLE';cpu='NOT_AVAILABLE';tokenPending='NOT_AVAILABLE';aiPending='NOT_AVAILABLE';storagePending='NOT_AVAILABLE'}};return $out}
function BucketObservations($d,$s){$start=[datetime]$s.startedAt;$prov=@();$stage=@();$res=@();foreach($l in Get-Content (Join-Path $d 'provider-metrics.jsonl')){try{$o=$l|ConvertFrom-Json;$prov+=[pscustomobject]@{t=[datetime]$o.timestamp;o=$o.payload}}catch{}};foreach($l in Get-Content (Join-Path $d 'stage-metrics.jsonl')){try{$o=$l|ConvertFrom-Json;$stage+=[pscustomobject]@{t=[datetime]$o.timestamp;o=$o.payload}}catch{}};foreach($l in Get-Content (Join-Path $d 'application-resources.jsonl')){try{$o=$l|ConvertFrom-Json;if($o.value-match'flux-corrected'){$res+=[pscustomobject]@{t=[datetime]$o.timestamp;cpu=[double](($o.value-split',')[1]-replace'%','')}}}catch{}};$out=@();foreach($i in 0..5){$lo=$start.AddSeconds(5*$i);$hi=$start.AddSeconds(5*($i+1));$pp=@($prov|Where-Object {$_.t-ge$lo -and $_.t-lt$hi});$ss=@($stage|Where-Object {$_.t-ge$lo -and $_.t-lt$hi});$rr=@($res|Where-Object {$_.t-ge$lo -and $_.t-lt$hi});$pending=@{token=@();ai=@();storage=@()};$ifs=@();foreach($x in $pp){foreach($m in @($x.o.metrics)){if($m.name-match'pending.connections'){$k=if($m.tags.name-match'doeng-token'){'token'}elseif($m.tags.name-match'doeng-ai'){'ai'}else{'storage'};$pending[$k]+=[double]$m.value}}};foreach($x in $ss){foreach($z in @($x.o.stages)){if($z.stage-in@('TOKEN','AI','STORAGE')){$ifs+=[int]$z.inFlight}}};$out+=[ordered]@{bucket="T$i";cpu=if($rr){($rr.cpu|Measure-Object -Average).Average}else{'NOT_AVAILABLE'};tokenPending=if($pending.token){($pending.token|Measure-Object -Maximum).Maximum}else{'NOT_AVAILABLE'};aiPending=if($pending.ai){($pending.ai|Measure-Object -Maximum).Maximum}else{'NOT_AVAILABLE'};storagePending=if($pending.storage){($pending.storage|Measure-Object -Maximum).Maximum}else{'NOT_AVAILABLE'};inFlight=if($ifs){($ifs|Measure-Object -Maximum).Maximum}else{'NOT_AVAILABLE'}}};$out}
$runMap=[ordered]@{'C600-100'='C600-100-R1';'C600-200'='C600-200-R1';'C600-150'='C600-150-R1'};$ids=@($runMap.Keys);$rows=@();foreach($cell in $ids){$id=$runMap[$cell];$d=Join-Path $root $id;$j=Get-Content (Join-Path $d 'load\client-results.json') -Raw|ConvertFrom-Json;$s=$j.summary;$rows+=[ordered]@{cell=$cell;runId=$id;valid=(Get-Content (Join-Path $d 'validity.json') -Raw|ConvertFrom-Json).valid;acceptedPerSecond=$s.successfulRequests/30;successRate=$s.successfulRequests/$s.completedRequests;http200P50=$s.latencyByOutcome.HTTP_200_ACCEPTED.p50;http200P95=$s.latencyByOutcome.HTTP_200_ACCEPTED.p95;http200P99=$s.latencyByOutcome.HTTP_200_ACCEPTED.p99;http200Max=$s.latencyByOutcome.HTTP_200_ACCEPTED.max;http500=$s.outcomeCounts.HTTP_500_UNCONTROLLED;http503=$s.outcomeCounts.HTTP_503_ADMISSION+$s.outcomeCounts.HTTP_503_DOWNSTREAM;timeout=$s.outcomeCounts.CLIENT_TIMEOUT;connectionError=$s.outcomeCounts.CONNECTION_ERROR;completedPerSecond=$s.throughputRequestsPerSecond;maxInFlight=$s.maxInFlight;resources=Resource (Join-Path $d 'application-resources.jsonl');provider=Provider (Join-Path $d 'provider-metrics.jsonl');buckets=Buckets $d $s;bucketObservations=BucketObservations $d $s}}
$groups=[ordered]@{};foreach($id in $ids){$r=@($rows|Where-Object {$_.cell -eq $id})[0];$groups[$id]=[ordered]@{acceptedPerSecond=$r.acceptedPerSecond;successRate=$r.successRate;http200P95=$r.http200P95;http200P99=$r.http200P99;http500=$r.http500;timeout=$r.timeout;connectionError=$r.connectionError;completedPerSecond=$r.completedPerSecond;maxInFlight=$r.maxInFlight;resources=$r.resources;provider=$r.provider;buckets=$r.buckets;bucketObservations=$r.bucketObservations}}
$result=[ordered]@{experiment='Exp158';generatedAt=[DateTime]::UtcNow.ToString('o');invalidInitialRuns=@('C600-100','C600-200','C600-150');invalidInitialRunReason='Harness template substitution left 200/700/200 in the rendered configuration; preserved and excluded.';runs=$rows;groups=$groups;staticC600Balance='NOT_SUPPORTED';screeningWinner='C600-200_NARROW_PRIMARY_ONLY';confirmationRun='NO';confirmationResult='NOT_RUN';timeDependentDegradation='SUPPORTED';backlogAccumulation='SUPPORTED';bestObservedStaticConfiguration='100/600/100_CONTROL_RETAINED; C600-200_NEAR_TIE';staticPoolSearch='CLOSED';nextControlStrategy='INCONCLUSIVE';nextRecommendedStep='Close C600 static search; any admission or logical-concurrency experiment requires a separate plan.';newPerformanceRunCount=3;totalExecutionAttempts=6;productionJavaChange='NONE';bucketNote='Replacement-run provider/resource bucket observations are timestamp-aligned; initial invalid runs are excluded from all conclusions.'}
New-Item -ItemType Directory -Force -Path (Split-Path $out)|Out-Null;$result|ConvertTo-Json -Depth 70|Set-Content $out -Encoding UTF8;Write-Output "EXP158_SUMMARY_WRITTEN $out"
